/* Signature Lithuanian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jonasvytautas": "From Jonas + Vytautas.", "Onadalia": "From Ona + Dalia.", "Petrasvytis": "From Petras + vytis (chase/knight).", "Marijatauta": "From Marija + tauta (people).", "Daliamedeina": "From Dalia + Medeina (forest goddess).", "Vytisalgis": "From vytis + Algis.", "Jonvytis": "Signature surname in -is style.", "Onadaliate": "Signature feminine surname in -aite style.", "Petrvytien": "Signature surname.", "Marijatautiene": "Signature feminine surname in -iene style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jonasvytautas';
console.log(lookup(q));

